esac
copy=0
for arg in "\$@"; do
  if [ "\$copy" = "1" ]; then cp "\$arg" "\$GH_STUB_DIR/last-body.md" 2>/dev/null; copy=0; fi
  [ "\$arg" = "--body-file" ] && copy=1
done
if [ "\$1 \$2" = "issue create" ]; then echo "https://github.com/OWNER/REPO/issues/42"; fi
exit 0
''');
